themes.css:
:root {
	/* Surfaces — all at hue 258 (violet) with 25-30% saturation so they read as desaturated brand colour, not grey. */
	--background-primary: hsl(258, 30%, 11%);
	--background-secondary: hsl(258, 28%, 15%);
	--background-secondary-alt: hsl(258, 30%, 13%);
	--background-tertiary: hsl(258, 35%, 7%);
	--background-textarea: hsl(258, 28%, 19%);
	--background-header-primary: hsl(258, 28%, 15%);
	--background-header-primary-hover: hsl(258, 30%, 18%);
	--background-header-secondary: hsl(258, 30%, 11%);
	/* Modifier overlays use brand-tinted hsla so highlights stay in the violet family. */
	--background-modifier-hover: hsla(258, 50%, 70%, 0.08);
	--background-modifier-selected: hsla(258, 60%, 70%, 0.16);
	--background-modifier-accent: hsla(258, 30%, 60%, 0.08);
	/* Brand */
	--brand-primary: #a98cf5;
	--brand-secondary: #8b6ddf;
	--brand-primary-light: #c0a8ff;
	--brand-primary-fill: #ffffff;
	--text-on-brand-primary: #ffffff;
	/* Text */
	--text-primary: #e4e4f7;
	--text-secondary: #b8b3d4;
	--text-tertiary: #8b86a8;
	--text-primary-muted: #b8b3d4;
	--text-link: #c0a8ff;
	/* Border lives a step above the lightest surface, same hue. */
	--border-color: hsl(258, 25%, 22%);
}

:root {
	/* Surfaces — hue 35 (amber) with 22-28% saturation. */
	--background-primary: hsl(35, 25%, 11%);
	--background-secondary: hsl(35, 22%, 15%);
	--background-secondary-alt: hsl(35, 25%, 13%);
	--background-tertiary: hsl(35, 30%, 7%);
	--background-textarea: hsl(35, 22%, 19%);
	--background-header-primary: hsl(35, 22%, 15%);
	--background-header-primary-hover: hsl(35, 25%, 18%);
	--background-header-secondary: hsl(35, 25%, 11%);
	/* Modifier overlays at the amber hue so highlights stay in family. */
	--background-modifier-hover: hsla(35, 60%, 65%, 0.08);
	--background-modifier-selected: hsla(35, 70%, 65%, 0.16);
	--background-modifier-accent: hsla(35, 40%, 60%, 0.08);
	/* Brand */
	--brand-primary: #f5b366;
	--brand-secondary: #d99850;
	--brand-primary-light: #f8c585;
	--brand-primary-fill: #1c1814;
	--text-on-brand-primary: #1c1814;
	/* Text */
	--text-primary: #ebe1d4;
	--text-secondary: #c8bba9;
	--text-tertiary: #968a7a;
	--text-primary-muted: #c8bba9;
	--text-link: #f8c585;
	/* Border same hue, lifted lightness. */
	--border-color: hsl(35, 22%, 22%);
}
